# Declaring State Variables with Different Visibility Levels

In Solidity, state variables can have three visibility levels: `public`, `internal`, and `private`. Here's how to declare each:

## Basic Syntax

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract VisibilityExample {
    // PUBLIC: Accessible everywhere, auto-generates a getter function
    uint256 public publicVar = 100;

    // INTERNAL: Accessible in this contract and derived contracts (default)
    uint256 internal internalVar = 200;

    // PRIVATE: Accessible only within this contract
    uint256 private privateVar = 300;

    // No specifier defaults to INTERNAL
    uint256 defaultVar = 400;
}
```

## Visibility Levels Explained

| Visibility | Same Contract | Derived Contracts | External Access |
|------------|:-------------:|:-----------------:|:---------------:|
| `public`   | ✅ | ✅ | ✅ (via getter) |
| `internal` | ✅ | ✅ | ❌ |
| `private`  | ✅ | ❌ | ❌ |

## Detailed Examples

### 1. Public Variables

```solidity
contract PublicExample {
    // Solidity automatically creates a getter function
    uint256 public count = 10;
    string public name = "Token";

    // Equivalent auto-generated getter:
    // function count() public view returns (uint256) { return count; }
}
```

### 2. Internal Variables

```solidity
contract Base {
    uint256 internal balance = 1000;
}

contract Derived is Base {
    function getBalance() public view returns (uint256) {
        return balance; // ✅ Can access internal variable from parent
    }
}
```

### 3. Private Variables

```solidity
contract Parent {
    uint256 private secret = 42;

    function getSecret() public view returns (uint256) {
        return secret; // ✅ Accessible within same contract
    }
}

contract Child is Parent {
    function trySecret() public view returns (uint256) {
        // return secret; // ❌ ERROR: private is NOT inherited
        return getSecret(); // ✅ Must use public/internal function
    }
}
```

## Important Notes

⚠️ **Privacy is not real secrecy!** Even `private` and `internal` variables are visible on the blockchain. Anyone can read them by inspecting contract storage. Never store sensitive data (passwords, keys) in any state variable.

```solidity
contract SecurityWarning {
    // This is readable by anyone inspecting the blockchain!
    uint256 private notReallySecret = 12345;
}
```

## Complete Practical Example

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract BankAccount {
    address public owner;           // Anyone can check the owner
    uint256 internal totalDeposits; // Shared with child contracts
    uint256 private secretPin;      // Only this contract

    constructor() {
        owner = msg.sender;
        totalDeposits = 0;
        secretPin = 1234;
    }

    function deposit(uint256 amount) public {
        totalDeposits += amount;
    }

    function verifyPin(uint256 pin) private view returns (bool) {
        return pin == secretPin;
    }
}
```

## Quick Tips

- **Default is `internal`** — but always specify visibility explicitly for clarity
- Use **`public`** when you need external read access
- Use **`internal`** for values shared with inheriting contracts
- Use **`private`** for contract-specific implementation details

